@GetMapping("/health")
ResponseEntity<Map<String, String>> health() {
    Map<String, String> body = Map.of("status", "UP");
    return ResponseEntity.status(HttpStatus.OK)
            .header("X-Health-Check", "javaquest")
            .body(body);
}

@PostMapping("/orders")
ResponseEntity<Map<String, Object>> createOrder(@RequestBody CreateOrderRequest request) {
    String newId = orderService.create(request);
    URI location = URI.create("/orders/" + newId);
    Map<String, Object> body = Map.of("id", newId);
    return ResponseEntity.created(location).body(body);
}
// Klient dostaje: 201 Created, Location: /orders/5

